/** Read-only fabrication preparation: no slicer or printer command is issued here. */
const permutations=([x,y,z])=>[[x,y,z],[x,z,y],[y,x,z],[y,z,x],[z,x,y],[z,y,x]];
export function inspectMission(state, projectId) {
  const project=state.projects.find(p=>p.id===projectId)||state.projects[0];
  if(!project)return null;
  const pieces=project.pieces.map(piece=>{
    const compatible=state.machines.filter(m=>m.tech===piece.tech&&permutations(piece.dims).some(d=>d.every((v,i)=>Number.isFinite(v)&&v>0&&v<=m.volume[i])));
    const job=state.jobs.find(j=>j.projectId===project.id&&j.pieceId===piece.id&&j.revision===(piece.revision||1));
    const machine=state.machines.find(m=>m.id===(job?.machine||piece.machine));
    return {id:piece.id,name:piece.name,revision:piece.revision||1,tech:piece.tech,dims:[...piece.dims],assetId:piece.assetId||null,compatibleMachines:compatible.map(m=>m.id),assignedMachine:job?.machine||piece.machine||null,assignmentSimulated:!!job,profileQualified:!!machine?.qualified,quantity:project.quantity||1,jobQuantity:job?.quantity??null};
  });
  const issues=[];
  if(!pieces.length)issues.push({code:'no_pieces',label:'Le dossier ne contient encore aucune pièce.',action:'import'});
  const missing=pieces.filter(p=>!p.assetId);if(missing.length)issues.push({code:'missing_geometry',label:`${missing.length} pièce${missing.length>1?'s':''} sans fichier STL importé.`,action:'import'});
  const oversized=pieces.filter(p=>!p.compatibleMachines.length);if(oversized.length)issues.push({code:'no_envelope_fit',label:`${oversized.length} pièce${oversized.length>1?'s':''} sans enveloppe compatible dans le parc.`,action:'wall-model'});
  const invalid=pieces.filter(p=>p.assignedMachine&&!p.compatibleMachines.includes(p.assignedMachine));if(invalid.length)issues.push({code:'incompatible_assignment',label:`${invalid.length} affectation${invalid.length>1?'s':''} à corriger.`,action:'plan'});
  const staleLot=pieces.filter(p=>p.jobQuantity!==null&&p.jobQuantity!==p.quantity);if(staleLot.length)issues.push({code:'quantity_changed',label:'La quantité du dossier diffère de lots déjà simulés. Ces lots sont conservés.',action:'plan'});
  const unqualified=pieces.filter(p=>!p.profileQualified);if(unqualified.length)issues.push({code:'unqualified_profiles',label:'Profils machine et matière à qualifier avant le slicing.',action:'connections'});
  issues.push({code:'slicer_not_connected',label:'Moteur de slicing local à raccorder.',action:'connections'});
  issues.push({code:'printers_not_connected',label:'Passerelle imprimantes à raccorder.',action:'connections'});
  return {format:'bojart.fabrication-preparation.v1',projectId:project.id,projectName:project.name,quantity:project.quantity||1,targetHeightMm:project.height??null,pieces,issues,canStartPhysicalPrint:false,canSlice:false,checks:{importedFiles:pieces.filter(p=>p.assetId).length,totalPieces:pieces.length,compatibleEnvelopes:pieces.filter(p=>p.compatibleMachines.length).length,simulatedAssignments:pieces.filter(p=>p.assignmentSimulated).length},limitations:['Enveloppes brutes uniquement ; rotations théoriques, supports et espacements non calculés.','La coupe 3D est une inspection géométrique et ne constitue pas un fichier de slicing.','Les binaires STL sont conservés séparément dans le navigateur.','Aucun fichier machine ni commande d’impression physique ne sont produits.']};
}

export function renderMission({mission:m,esc,icon}){
  if(!m)return '<p>Aucun dossier actif.</p>';
  const c=m.checks,steps=[['01','Les fichiers',`${c.importedFiles} / ${c.totalPieces} STL importés`,c.totalPieces>0&&c.importedFiles===c.totalPieces,'import'],['02','Les aperçus','Volume, maillage et coupe 3D',false,'wall-model'],['03','La répartition',`${c.simulatedAssignments} affectations simulées`,c.totalPieces>0&&c.simulatedAssignments===c.totalPieces,'plan'],['04','Le slicing','Moteur local à raccorder',false,'connections'],['05','La validation','Supports, matières et plateaux',false,'connections'],['06','La fabrication','Passerelle machines à raccorder',false,'connections']];
  return `<div class="mission-intro"><span class="tag tag-red">PRÉPARATION DU PROJET</span><h3>${esc(m.projectName)}</h3><p>${m.quantity} exemplaire${m.quantity>1?'s':''} · ${c.totalPieces} pièces · ${m.targetHeightMm===null?'hauteur à préciser':'hauteur souhaitée '+m.targetHeightMm+' mm'}</p></div><div class="mission-steps">${steps.map(([n,title,sub,done,action])=>`<button class="mission-step ${done?'ready':''}" data-action="${action}"><span class="mission-step-number">${done?icon('check'):n}</span><div><strong>${title}</strong><small>${sub}</small></div>${icon('arrowUp')}</button>`).join('')}</div><div class="mission-findings"><p class="eyebrow">CE QUI RESTE À PRÉPARER</p>${m.issues.map(issue=>`<button data-action="${issue.action}"><i></i><span>${esc(issue.label)}</span>${icon('arrow')}</button>`).join('')}</div><div class="mission-pieces"><h3>La bonne pièce, la bonne ressource.</h3>${m.pieces.map(p=>`<div><span><strong>${esc(p.name)}</strong><small>${p.dims.join(' × ')} mm · ${p.tech==='fdm'?'FDM':'résine UV'}</small></span><span class="tag ${p.compatibleMachines.length?'tag-red':'tag-amber'}">${p.assignedMachine?esc(p.assignedMachine):p.compatibleMachines.length?p.compatibleMachines.length+' possibles':'À segmenter'}</span></div>`).join('')}</div><p class="micro-copy form-section">Correspondance sur le procédé et le volume brut. Le placement, les supports et le profil ne sont pas encore validés. Le démarrage physique reste indisponible.</p><div class="form-actions"><button class="button button-red" data-action="plan">${icon('layers')} Répartir en simulation</button><button class="button" data-action="export-mission">${icon('save')} Exporter la préparation</button></div>`;
}
